package chat.server

import scala.collection.mutable
import scala.concurrent.{Future, Promise, ExecutionContext}
import java.util.concurrent.{ConcurrentHashMap, atomic}
import java.util.concurrent.atomic.{AtomicReference, AtomicInteger}

case class ConnectionId(value: Long)
case class Message(sender: ConnectionId, content: String, timestamp: Long)

trait ConnectionHandle {
  def id: ConnectionId
  def send(msg: Message): Future[Unit]
  def isAlive: Boolean
  def close(): Unit
}

class ConnectionPool(maxSize: Int)(implicit ec: ExecutionContext) {
  private val pool = new ConcurrentHashMap[ConnectionId, AtomicReference[ConnectionHandle]]()
  private val recycleQueue = new java.util.concurrent.LinkedBlockingQueue[ConnectionId]()
  private val epoch = new AtomicInteger(0)

  def acquire(handle: ConnectionHandle): Unit = {
    val ref = new AtomicReference[ConnectionHandle](handle)
    pool.put(handle.id, ref)
  }

  def release(id: ConnectionId): Unit = {
    val ref = pool.get(id)
    if (ref != null) {
      val handle = ref.getAndSet(null)
      if (handle != null) {
        handle.close()
        recycleQueue.offer(id)
      }
    }
  }

  def getRef(id: ConnectionId): AtomicReference[ConnectionHandle] = pool.get(id)

  def sweep(): Unit = {
    epoch.incrementAndGet()
    val iter = pool.entrySet().iterator()
    while (iter.hasNext) {
      val entry = iter.next()
      val ref = entry.getValue
      val handle = ref.get()
      if (handle != null && !handle.isAlive) {
        release(entry.getKey)
        iter.remove()
      }
    }
  }
}

class ChatRoom(name: String, pool: ConnectionPool)(implicit ec: ExecutionContext) {
  private val members = mutable.Set[ConnectionId]()
  private val pendingCallbacks = new ConcurrentHashMap[ConnectionId, List[Message => Unit]]()

  def join(connId: ConnectionId): Unit = synchronized {
    members += connId
    pendingCallbacks.put(connId, Nil)
  }

  def leave(connId: ConnectionId): Unit = synchronized {
    members -= connId
    pendingCallbacks.remove(connId)
    pool.release(connId)
  }

  def registerCallback(connId: ConnectionId, cb: Message => Unit): Unit = {
    pendingCallbacks.compute(connId, (_, existing) => {
      if (existing == null) List(cb)
      else cb :: existing
    })
  }

  def broadcast(msg: Message): Future[Unit] = {
    val targets = synchronized { members.toList }
    val futures = targets.map { connId =>
      deliverWithRetry(connId, msg, retries = 3)
    }
    Future.sequence(futures).map(_ => ())
  }

  private def deliverWithRetry(connId: ConnectionId, msg: Message, retries: Int): Future[Unit] = {
    val connRef = pool.getRef(connId)
    if (connRef == null) return Future.successful(())

    val capturedRef = connRef
    val handle = capturedRef.get()

    if (handle == null) {
      if (retries > 0) {
        Future {
          Thread.sleep(10)
        }.flatMap(_ => deliverWithRetry(connId, msg, retries - 1))
      } else {
        Future.successful(())
      }
    } else {
      handle.send(msg).recoverWith {
        case _: Exception if retries > 0 =>
          scheduleRedelivery(capturedRef, msg, retries - 1)
      }
    }
  }

  private def scheduleRedelivery(
    connRef: AtomicReference[ConnectionHandle],
    msg: Message,
    retries: Int
  ): Future[Unit] = {
    Future {
      Thread.sleep(50)
    }.flatMap { _ =>
      val handle = connRef.get()
      if (handle != null) {
        handle.send(msg).recoverWith {
          case _: Exception if retries > 0 =>
            scheduleRedelivery(connRef, msg, retries - 1)
        }
      } else {
        Future.successful(())
      }
    }
  }
}

class RealtimeChatServer(implicit ec: ExecutionContext) {
  private val pool = new ConnectionPool(1000)
  private val rooms = new ConcurrentHashMap[String, ChatRoom]()
  private val connectionEpochs = new ConcurrentHashMap[ConnectionId, AtomicInteger]()

  def createRoom(name: String): ChatRoom = {
    val room = new ChatRoom(name, pool)
    rooms.put(name, room)
    room
  }

  def connect(handle: ConnectionHandle): Unit = {
    pool.acquire(handle)
    connectionEpochs.put(handle.id, new AtomicInteger(0))
  }

  def disconnect(connId: ConnectionId, roomName: String): Unit = {
    val room = rooms.get(roomName)
    if (room != null) {
      room.leave(connId)
    }
    connectionEpochs.remove(connId)
  }

  def sendMessage(roomName: String, msg: Message): Future[Unit] = {
    val room = rooms.get(roomName)
    if (room != null) room.broadcast(msg)
    else Future.successful(())
  }

  def reconnect(oldId: ConnectionId, newHandle: ConnectionHandle, roomName: String): Unit = {
    val epochRef = connectionEpochs.get(oldId)
    if (epochRef != null) epochRef.incrementAndGet()

    pool.release(oldId)
    pool.acquire(newHandle)
    connectionEpochs.put(newHandle.id, new AtomicInteger(0))

    val room = rooms.get(roomName)
    if (room != null) {
      room.leave(oldId)
      room.join(newHandle.id)
    }
  }
}
